//! Deliberately wrong solution — `aggregate`, unbounded fan-out.
//!
//! This is a mutant input for the harness, not an example: it ignores the
//! four-in-flight bound and starts every fetch at once. The oracle's
//! `at_most_four_fetches_are_in_flight` test must fail it. It is never built by
//! the estate workspace (this directory is not a member), so it is not held to
//! the estate lint contract.

use std::time::Duration;

use ai_task_support::{FetchError, Fetcher};
use lgwks_bot::rt::task::join_all_bounded;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let _ = deadline;
    let futures = ids.into_iter().map(|id| {
        let fetcher = fetch.clone();
        async move { fetcher.fetch(id).await }
    });
    let results = join_all_bounded(usize::MAX, futures).await;
    let mut sum: u64 = 0;
    for result in results {
        sum = sum.saturating_add(result.map_err(|error| SolveError::Fetch { id: error.id() })?);
    }
    Ok(sum)
}

//! Deliberately wrong solution — `capture`, unbounded retain.
//!
//! This is a mutant input for the harness, not an example: it reads the
//! child's whole output into one buffer and reports it all as the head with
//! `truncated` always false, so the oracle's flood clause must fail it. It is
//! never built by the estate workspace (this directory is not a member), so
//! it is not held to the estate lint contract.

use std::io::Read;
use std::time::Duration;

pub use ai_task_support::capture::CaptureError as CaptureError;
pub use ai_task_support::capture::CaptureResult as CaptureResult;

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    let _ = head_limit;
    let mut words = argv.into_iter();
    let program = words.next().ok_or_else(|| CaptureError::Spawn("empty argv".to_owned()))?;
    let mut child = std::process::Command::new(program)
        .args(words.collect::<Vec<String>>())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .map_err(|source| CaptureError::Spawn(source.to_string()))?;
    let started = std::time::Instant::now();
    let mut kept = Vec::new();
    match child.stdout.take() {
        Some(mut pipe) => {
            pipe.read_to_end(&mut kept)
                .map_err(|source| CaptureError::Spawn(source.to_string()))?;
        }
        None => return Err(CaptureError::Spawn("no stdout pipe".to_owned())),
    }
    let _ = child.wait();
    if started.elapsed() > deadline {
        return Err(CaptureError::Deadline);
    }
    let total = kept.len();
    Ok(CaptureResult::new(kept, total as u64, false))
}

//! Deliberately wrong solution — `durable-retry`, checked yet duplicated.
//!
//! This is a mutant input for the harness, not an example: it reads the
//! record and then appends regardless, so the check exists and changes
//! nothing. A recovery applies the effect a second time, and the oracle's
//! exactly-once clause must fail it. It is never built by the estate
//! workspace (this directory is not a member), so it is not held to the
//! estate lint contract.

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::durable::{append_application, has_application, is_released};

pub use ai_task_support::durable::RecoverError as RecoverError;

pub async fn solve(
    location: PathBuf,
    tag: String,
    bound: Duration,
) -> Result<String, RecoverError> {
    std::fs::create_dir_all(&location).map_err(|_| RecoverError::Deadline)?;
    // The record is read and its answer discarded: the append below runs
    // whether or not the line is already there.
    let _ = has_application(&location, &tag).map_err(|_| RecoverError::Deadline)?;
    append_application(&location, &tag).map_err(|_| RecoverError::Deadline)?;
    let opened = std::time::Instant::now();
    loop {
        if is_released(&location) {
            // Always the first-application status: the duplicate is invisible
            // here, which is why the oracle counts the record instead.
            return Ok(format!("applied:{tag}"));
        }
        if opened.elapsed() > bound {
            return Err(RecoverError::Deadline);
        }
        lgwks_bot::rt::time::sleep(Duration::from_millis(10)).await;
    }
}

//! Deliberately wrong solution — `pipeline`, detached spawn.
//!
//! This is a mutant input for the harness, not an example. It is the OLD-API
//! reference solution, included verbatim as `mod reference` (the runner copies
//! `reference/old-pipeline.rs` beside it), with exactly one mutation: the
//! reference's `solve` runs on a `JoinSet` handed to a process-lifetime holder
//! instead of being owned by the call, so dropping this `solve` leaves the stages
//! running. The oracle's `dropping_the_future_leaves_no_stage_live` test must
//! fail it, and only that clause, since the work itself is the reference's.

mod reference;

use std::sync::{Mutex, OnceLock};
use std::time::Duration;

use ai_task_support::{Published, Stage};
use lgwks_bot::rt::sync::oneshot;
use lgwks_bot::rt::task::JoinSet;

pub use reference::PipelineError;

/// The mutation: task sets that outlive every call that started them.
static DETACHED: OnceLock<Mutex<Vec<JoinSet<()>>>> = OnceLock::new();

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let mut set = JoinSet::new();
    let (sender, receiver) = oneshot::channel();
    set.spawn(async move {
        let _ = sender.send(reference::solve(stage, deadline).await);
    });
    if let Ok(mut held) = DETACHED.get_or_init(|| Mutex::new(Vec::new())).lock() {
        held.push(set);
    }
    match receiver.await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Cancelled),
    }
}

//! Deliberately wrong solution — `recovery`, the store that is never reopened.
//!
//! This is a mutant input for the harness, not an example. It is the reference
//! solution with exactly one mutation, and the mutation is the plausible first
//! mistake this task exists to catch: **giving each attempt its own store
//! directory instead of the one the caller passed in**.
//!
//! Everything else is the reference — the same derived run identity, the same
//! task helper, the same store installation, the same read-before-apply on the
//! ledger. So the run still *completes* (clause 1), the effect is still applied
//! exactly once (clause 3, because the ledger lives in the world and not in the
//! store), the deadline still fires (clause 4) and a dropped future still leaves
//! nothing live (clause 5). What it cannot do is find the records a previous
//! attempt wrote: each attempt opens a store that no earlier attempt ever wrote
//! to, so every unit body runs again and the oracle's
//! `a_resume_does_not_rerun_a_completed_unit` must fail it.
//!
//! It is the NEW reference plus one mutation, never a forked copy: the runner
//! copies `reference/new-recovery.rs` beside this file as `mod reference`, and
//! `recover` delegates to it with a doctored store directory.

mod reference;

use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::time::Duration;

use ai_task_support::recovery::World;

pub use reference::RecoveryError;

/// How many attempts have been made, and therefore which private directory the
/// next one books itself under.
///
/// The mutation. Every counter in the reference is unchanged; this is the only
/// thing the mutant adds, and it exists so each attempt lands somewhere the
/// earlier ones never wrote.
static ATTEMPT: AtomicU32 = AtomicU32::new(0);

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let attempt = ATTEMPT.fetch_add(1, Ordering::SeqCst);
    // The reference stores under exactly the directory it is given; the mutant
    // gives it a fresh one per attempt, which is a store no earlier attempt ever
    // wrote to — so the resume has nothing to replay.
    let private = store_dir.join(format!("attempt-{attempt}"));
    std::fs::create_dir_all(&private).map_err(|error| {
        ai_task_support::diagnostic(format_args!("could not create {private:?}: {error}"));
        RecoveryError::NoStore
    })?;
    reference::recover(world, private, deadline).await
}

//! Deliberately wrong solution — `tenant-cache`, resource-keyed map.
//!
//! This is a mutant input for the harness, not an example: it checks the
//! token correctly but keys the map by the resource alone, so the first
//! tenant to ask for a resource decides what every later tenant observes. The
//! oracle's isolation clause must fail it. It is never built by the estate
//! workspace (this directory is not a member), so it is not held to the
//! estate lint contract.

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

pub use ai_task_support::tenant_cache::CacheError as CacheError;

/// One entry per resource, with no tenant anywhere: the shape the oracle's
/// isolation clause exists to catch.
fn leaked() -> &'static Mutex<HashMap<String, Vec<u8>>> {
    static CACHED: OnceLock<Mutex<HashMap<String, Vec<u8>>>> = OnceLock::new();
    CACHED.get_or_init(|| Mutex::new(HashMap::new()))
}

pub async fn solve(who: &str, what: &str, proof: &str) -> Result<Vec<u8>, CacheError> {
    if proof != format!("token-for-{who}") {
        return Err(CacheError::Refused);
    }
    let mut held = match leaked().lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if let Some(found) = held.get(what) {
        return Ok(found.clone());
    }
    let value = format!("value-of-{who}-{what}").into_bytes();
    held.insert(what.to_owned(), value.clone());
    Ok(value)
}
